package server

// idempotency_pilot_test.go — Task 6.3 pilot: proves that queue-bff's
// :publish route is wrapped in idempotency.Middleware and a replayed
// Idempotency-Key does not re-invoke PublishPost a second time. An
// irreversible double-post to a real social account is the nearest thing
// in this repo to a double-charge, which is why :publish is in the pilot
// set alongside :schedule and :bulk-import.
//
// Uses a REAL signed JWT (via the orgClaimOIDCStub helper already defined
// in router_org_claim_test.go) so the request reaches the wrapped handler,
// not just the router tree.

import (
	"bytes"
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"

	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	postv1 "github.com/zenithflowinc/omnicore-platform/platform/proto/gen/go/omnicore/queue/post/v1"
	"github.com/zenithflowinc/omnicore-platform/services/queue-bff/internal/handlers"
)

// countingPostClient wraps fakePostClient to count PublishPost invocations,
// so a test can assert a replayed key produced no second live post.
type countingPostClient struct {
	fakePostClient
	publishCalls int32
}

func (c *countingPostClient) PublishPost(ctx context.Context, req *postv1.PublishPostRequest, opts ...grpc.CallOption) (*postv1.PublishPostResponse, error) {
	atomic.AddInt32(&c.publishCalls, 1)
	return c.fakePostClient.PublishPost(ctx, req, opts...)
}

func TestPilot_PostPublish_ReplayedKey_NoSecondPost(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-pilot-1")

	client := &countingPostClient{}
	store := idempotency.NewMemStore()

	h := New(Deps{
		Verifier:  verifier,
		PostH:     handlers.NewPostHandler(client),
		IdemStore: store,
	})

	const idemKey = "9c858e4e-1e3d-4f0a-9d0e-000000000201"

	do := func() *httptest.ResponseRecorder {
		req := httptest.NewRequest(http.MethodPost, "/api/v1/queue/posts/p-1:publish", bytes.NewBufferString(`{}`))
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Authorization", "Bearer "+token)
		req.Header.Set(idempotency.HeaderName, idemKey)
		rr := httptest.NewRecorder()
		h.ServeHTTP(rr, req)
		return rr
	}

	first := do()
	require.NotEqual(t, http.StatusNotFound, first.Code)

	second := do()
	require.Equal(t, first.Code, second.Code)
	require.Equal(t, first.Body.String(), second.Body.String())

	require.EqualValues(t, 1, atomic.LoadInt32(&client.publishCalls),
		"replayed Idempotency-Key must not trigger a second live post to the social account")
}

func TestPilot_PostPublish_DifferentOrgs_SameKey_BothExecute(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	tokenA := stub.mintToken(t, orgClaimTestAudience, "org-pilot-A")
	tokenB := stub.mintToken(t, orgClaimTestAudience, "org-pilot-B")

	client := &countingPostClient{}
	store := idempotency.NewMemStore()

	h := New(Deps{
		Verifier:  verifier,
		PostH:     handlers.NewPostHandler(client),
		IdemStore: store,
	})

	const idemKey = "9c858e4e-1e3d-4f0a-9d0e-000000000202"

	req := func(token string) *httptest.ResponseRecorder {
		r := httptest.NewRequest(http.MethodPost, "/api/v1/queue/posts/p-1:publish", bytes.NewBufferString(`{}`))
		r.Header.Set("Content-Type", "application/json")
		r.Header.Set("Authorization", "Bearer "+token)
		r.Header.Set(idempotency.HeaderName, idemKey)
		rr := httptest.NewRecorder()
		h.ServeHTTP(rr, r)
		return rr
	}

	respA := req(tokenA)
	respB := req(tokenB)
	require.NotEqual(t, http.StatusNotFound, respA.Code)
	require.NotEqual(t, http.StatusNotFound, respB.Code)

	require.EqualValues(t, 2, atomic.LoadInt32(&client.publishCalls),
		"two different orgs using the same client-generated key must both execute")
}


