// TestAuthenticatedRoutes_MissingJWT_Returns401 is the BFF trust-boundary
// invariant on the route surface: every one of the authenticated
// PostService/AccountService/AccountTagService/TriggerService/
// AnalyticsService routes must be reachable (registered — proven by NOT
// 404) but gated closed (401, not the handler's own response) when no
// bearer token is presented. A 404 here would mean the route never got
// wired; a 200/201/etc. would mean the auth middleware isn't actually
// mounted on that route.
func TestAuthenticatedRoutes_MissingJWT_Returns401(t *testing.T) {
	h := New(fullyWiredDeps())

	cases := []struct {
		name   string
		method string
		path   string
	}{
		// Posts
		{"PostList", http.MethodGet, "/api/v1/queue/posts"},
		{"PostCreate", http.MethodPost, "/api/v1/queue/posts"},
		{"PostGet", http.MethodGet, "/api/v1/queue/posts/p1"},
		{"PostUpdate", http.MethodPut, "/api/v1/queue/posts/p1"},
		{"PostDelete", http.MethodDelete, "/api/v1/queue/posts/p1"},
		{"PostSchedule", http.MethodPost, "/api/v1/queue/posts/p1:schedule"},
		{"PostPublish", http.MethodPost, "/api/v1/queue/posts/p1:publish"},
		{"PostRevert", http.MethodPost, "/api/v1/queue/posts/p1:revert"},
		{"PostBulkUpdate", http.MethodPost, "/api/v1/queue/posts:bulk-update"},
		{"PostBulkDelete", http.MethodPost, "/api/v1/queue/posts:bulk-delete"},
		{"PostBulkImport", http.MethodPost, "/api/v1/queue/posts:bulk-import"},
		// Accounts
		{"AccountList", http.MethodGet, "/api/v1/queue/accounts"},
