// ---------- Admin-plane confinement (Security Invariant #8) ----------

// TestRejectAdminRoles_AdminClaims_Returns403 drives auth.RejectAdminRoles()
// directly with an admin-realm-role claim already on the context — this is
// the unit-testable seam given the server tests don't wire a real JWT
// verifier. It proves the exact middleware queue-bff mounts denies admin
// tokens.
func TestRejectAdminRoles_AdminClaims_Returns403(t *testing.T) {
	mw := auth.RejectAdminRoles()

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	claims := auth.Claims{OrgID: "org-7", Subject: "admin-1", Roles: []string{"admin"}}
	req = req.WithContext(auth.ClaimsIntoContext(req.Context(), claims))
	rr := httptest.NewRecorder()

	mw(next).ServeHTTP(rr, req)

	if rr.Code != http.StatusForbidden {
		t.Fatalf("status = %d; want 403 for an admin-realm-role token", rr.Code)
	}
	if nextCalled {
		t.Fatal("next handler must NOT be called for an admin-realm-role token")
	}
}

// TestRejectAdminRoles_NonAdminClaims_PassesThrough asserts a workspace user
// (no admin/org-admin realm role) is let through.
func TestRejectAdminRoles_NonAdminClaims_PassesThrough(t *testing.T) {
	mw := auth.RejectAdminRoles()

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	claims := auth.Claims{OrgID: "org-7", Subject: "user-42", Roles: []string{"member"}}
	req = req.WithContext(auth.ClaimsIntoContext(req.Context(), claims))
	rr := httptest.NewRecorder()

	mw(next).ServeHTTP(rr, req)

	if rr.Code == http.StatusForbidden {
		t.Fatal("got 403 for a non-admin claim — RejectAdminRoles must pass it through")
	}
	if !nextCalled {
		t.Fatal("next handler must be called for a non-admin-role token")
	}
}

// ---------- Feature flag gate ----------

// queueFlagDisabledBody is the JSON shape emitted by RequireVerticalEnabled.
type queueFlagDisabledBody struct {
	Error struct {
		Code string `json:"code"`
	} `json:"error"`
}

// makeQueueFlagCache returns a featureflags.Cache whose fetcher always
// returns the provided enabled value for the "queue" vertical.
func makeQueueFlagCache(enabled bool) *featureflags.Cache {
	return featureflags.NewCache(func(_ context.Context) (map[string]bool, error) {
		return map[string]bool{"queue": enabled}, nil
	}, 10*time.Second, slog.Default())
}

// TestQueueVerticalGate_MiddlewareDisabled_Returns403 tests the
// RequireVerticalEnabled middleware directly — bypassing the full server
// stack (which would return 401 from JWT auth before reaching the gate) —
// to verify it returns 403 with vertical_disabled when the cache reports
// disabled.
func TestQueueVerticalGate_MiddlewareDisabled_Returns403(t *testing.T) {
	cache := makeQueueFlagCache(false)
	mw := featureflags.RequireVerticalEnabled(cache, "queue")

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	rr := httptest.NewRecorder()
	mw(next).ServeHTTP(rr, req)

	if rr.Code != http.StatusForbidden {
		t.Fatalf("expected 403 when vertical disabled, got %d", rr.Code)
	}
	if nextCalled {
		t.Fatal("next handler must NOT be called when vertical is disabled")
	}
	var body queueFlagDisabledBody
	if err := json.NewDecoder(rr.Body).Decode(&body); err != nil {
		t.Fatalf("failed to decode body: %v", err)
	}
	if body.Error.Code != "vertical_disabled" {
		t.Errorf("error code = %q, want %q", body.Error.Code, "vertical_disabled")
	}
}

// TestQueueVerticalGate_MiddlewareEnabled_PassesThrough asserts that when
// the queue vertical is enabled, the middleware calls next.
func TestQueueVerticalGate_MiddlewareEnabled_PassesThrough(t *testing.T) {
	cache := makeQueueFlagCache(true)
	mw := featureflags.RequireVerticalEnabled(cache, "queue")

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	rr := httptest.NewRecorder()
	mw(next).ServeHTTP(rr, req)

	if rr.Code == http.StatusForbidden {
		t.Fatalf("got 403 vertical_disabled even though vertical is enabled")
	}
	if !nextCalled {
		t.Fatal("next handler must be called when vertical is enabled")
	}
}

// TestQueueVerticalGate_NilCache_PassesThrough asserts that a nil
// FeatureFlagCache (ORG_SVC_ADDR unset in local dev) is a pass-through.
func TestQueueVerticalGate_NilCache_PassesThrough(t *testing.T) {
	// nil cache — gate must be a no-op so existing routes still return 401
	// (auth gated) rather than 403 (flag disabled).
	h := New(fullyWiredDeps())

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	if rr.Code == http.StatusForbidden {
		t.Fatalf("got 403 with nil cache — nil must be a pass-through")
	}
}

// TestQueueVerticalGate_DepField_IsWired asserts that Deps.FeatureFlagCache
// is accepted by New without panicking.
func TestQueueVerticalGate_DepField_IsWired(t *testing.T) {
	deps := fullyWiredDeps()
	deps.FeatureFlagCache = makeQueueFlagCache(true)
	// Must not panic.
	_ = New(deps)
}

// mountClientIPProbe adds a diagnostic route that echoes security.ClientIP(r)
// as the response body. New()'s underlying *chi.Mux only builds its handler
// once (on the first route add inside New itself); inserting one more route
// into the still-live radix tree afterward is safe and lets tests observe
// what the ClientIP middleware resolved without needing a production route
// that exposes it.
func mountClientIPProbe(t *testing.T, h http.Handler) {
	t.Helper()
	mux, ok := h.(chi.Router)
	if !ok {
		t.Fatalf("New() did not return a chi.Router (got %T)", h)
	}
	mux.Get("/__test_clientip", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte(security.ClientIP(r)))
	})
}

// TestClientIPMiddleware_UntrustedRemoteAddr_IgnoresForgedXFF proves that a
// direct caller (RemoteAddr outside TrustedProxyCIDRs) cannot spoof its
// resolved client IP via X-Forwarded-For — closing the gap RealIP left open.
func TestClientIPMiddleware_UntrustedRemoteAddr_IgnoresForgedXFF(t *testing.T) {
	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	h := New(Deps{TrustedProxyCIDRs: trusted})
	mountClientIPProbe(t, h)

	req := httptest.NewRequest(http.MethodGet, "/__test_clientip", nil)
	req.RemoteAddr = "203.0.113.9:12345" // NOT in the trusted set
	req.Header.Set("X-Forwarded-For", "198.51.100.1")
	req.Header.Set("True-Client-IP", "198.51.100.1")
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	if got, want := rr.Body.String(), "203.0.113.9"; got != want {
		t.Errorf("ClientIP = %q, want %q (forged XFF from an untrusted peer must be ignored)", got, want)
	}
}

// TestClientIPMiddleware_TrustedRemoteAddr_HonorsXFF proves that a request
// proxied through a peer inside TrustedProxyCIDRs resolves to the real
// client IP carried in X-Forwarded-For.
func TestClientIPMiddleware_TrustedRemoteAddr_HonorsXFF(t *testing.T) {
	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	h := New(Deps{TrustedProxyCIDRs: trusted})
	mountClientIPProbe(t, h)

	req := httptest.NewRequest(http.MethodGet, "/__test_clientip", nil)
	req.RemoteAddr = "10.0.0.5:12345" // inside the trusted set
	req.Header.Set("X-Forwarded-For", "198.51.100.1")
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)

	if got, want := rr.Body.String(), "198.51.100.1"; got != want {
		t.Errorf("ClientIP = %q, want %q (legitimately proxied request should resolve to the real client)", got, want)
	}
}


