// Package server holds the HTTP router for queue-bff.
//
// Retrofitted (T21, epic #2431) onto platform/libs/go/bffserver: this
// router's shape — root chassis, /healthz + /readyz + /metrics, and a
// single authenticated route group with the standard 5-middleware chain —
// is an exact match for the shared bffserver.NewRouter/Authenticated
// skeleton, so New below is now a thin composition of the two rather than
// a hand-rolled copy. queue-bff is the REST→gRPC trust boundary in front
// of queue-svc: every authenticated route validates the user JWT
// (auth.HTTPMiddleware) and the handlers mint + forward the platform x-*
// headers from validated claims onto the gRPC call (auth.ForwardingContext).
//
// Unlike ask-bff, queue-bff has NO unauthenticated public route group — the
// Queue vertical has no external respondent-facing surface. Every
// /api/v1/queue/** route requires a validated bearer JWT, rejects
// realm-admin tokens, gates on the queue feature flag, and rate-limits per
// (org_id, IP).
//
// Public health probes (/healthz, /readyz) and the Prometheus scrape
// endpoint (/metrics) sit outside the authenticated group.
package server

import (
	"net/http"
	"net/netip"
	"time"

	"github.com/go-chi/chi/v5"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/bffserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/featureflags"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	"github.com/zenithflowinc/omnicore-platform/services/queue-bff/internal/handlers"
	"github.com/zenithflowinc/omnicore-platform/services/queue-bff/internal/queueclient"
)

// authenticatedGroupTimeout bounds total request duration on every route in
// the authenticated group. queueclient.Dial's TierDefault (30s) gRPC
// deadline is the longest synchronous call any route here makes
// (rangeclient is TierFast, 5s) — 35s gives that gRPC deadline headroom to
// fire and be mapped to an HTTP error before this HTTP-level Timeout would
// otherwise fire first. No route in this service streams (Flusher/SSE/
// multipart) — see the Task 5 audit — so a single group-wide Timeout is
// safe with no per-route exemption needed.
//
// A var, not a const: tests shrink it to keep a wedged-downstream test fast
// and immune to httpserver.Timeout's process-wide OMNICORE_TIMEOUT_SCALE
// cache (which locks in at the first Timeout() call across this whole test
// binary, not per-test) — see timeout_test.go.
var authenticatedGroupTimeout = 35 * time.Second

// Stater is an alias for bffserver.Stater, kept so existing call sites
// (Deps.QueueClient's type, any external reference to server.Stater) don't
// need to change.
type Stater = bffserver.Stater

// Deps groups the runtime dependencies the router needs.
type Deps struct {
	// MetricsHandler serves the Prometheus /metrics scrape endpoint (PUBLIC).
	// MetricsMiddleware wraps the entire router to record every request.
	// Both are set by main.go via observability after SetupMeter.
	MetricsHandler    http.Handler
	MetricsMiddleware func(http.Handler) http.Handler

	Verifier *auth.JWTVerifier
	// QueueClient supplies the connectivity state for /readyz.
	QueueClient Stater
	// QueueTypedClient is the full queueclient.Client used to construct the
	// Post/Account/AccountTag/Trigger/Analytics handlers. Kept separate from
	// QueueClient so tests that only need /healthz + /readyz can pass a nil
	// typed client.
	QueueTypedClient *queueclient.Client

	// FeatureFlagCache is an optional TTL-backed feature-flag cache. When
	// non-nil, RequireVerticalEnabled("queue") is mounted on the
	// authenticated route group and returns 403 vertical_disabled when
	// org-svc reports the queue vertical is disabled. A nil cache is a
	// pass-through no-op (fail-safe-open for local dev when ORG_SVC_ADDR is
	// not configured).
	FeatureFlagCache *featureflags.Cache

	// PostH / AccountH / AccountGroupH / AccountTagH / TriggerH / AnalyticsH
	// may be injected directly by tests (without a live gRPC client). When
	// non-nil each takes precedence over the handler built from the typed
	// client. Each route group is guarded independently on its own handler
	// being non-nil, so a test can wire just one without the others
	// panicking on a nil receiver.
	PostH         *handlers.PostHandler
	AccountH      *handlers.AccountHandler
	AccountGroupH *handlers.AccountGroupHandler
	AccountTagH   *handlers.AccountTagHandler
	TriggerH      *handlers.TriggerHandler
	AnalyticsH    *handlers.AnalyticsHandler

	// RangeExercisesH backs GET /api/v1/queue/range/exercises (Publish 3a's
	// exercise picker). Unlike the handlers above, main.go constructs this
	// handler UNCONDITIONALLY (with a nil rangeclient when RANGE_SVC_ADDR is
	// unset) so the route is always mounted — a misconfigured deployment
	// gets a clean 503 from the handler itself rather than a 404 that looks
	// like a routing bug. A nil Deps.RangeExercisesH (e.g. a test that
	// doesn't care about this route) simply leaves it unmounted, same as
	// every other handler field here.
	RangeExercisesH *handlers.RangeExercisesHandler

	// TrustedProxyCIDRs is the set of CIDR ranges trusted to supply a
	// truthful X-Forwarded-For / True-Client-IP chain, consumed by
	// security.ClientIPMiddleware. A request whose immediate peer
	// (RemoteAddr) falls outside this set has its client IP resolved from
	// RemoteAddr alone — any forged forwarding header is ignored.
	TrustedProxyCIDRs []netip.Prefix

	// IdemStore is the optional idempotency.Store wrapping queue-bff's Task
	// 6.3 pilot routes: :schedule, :publish, :bulk-import — the nearest
	// thing here to a double-charge (an irreversible double-post to a real
	// social account). A nil store (the default) makes idemMiddleware a
	// pass-through no-op, matching the nil-handler discipline used
	// elsewhere in Deps.
	IdemStore idempotency.Store
}

// idemMiddleware wraps store with idempotency.Middleware, or is a
// pass-through no-op when store is nil. See Deps.IdemStore.
func idemMiddleware(store idempotency.Store) func(http.Handler) http.Handler {
	if store == nil {
		return func(next http.Handler) http.Handler { return next }
	}
	return idempotency.Middleware(store)
}

// New returns a chi.Router wired with middleware + /healthz + /readyz +
// /metrics + the authenticated PostService/AccountService/
// AccountTagService/TriggerService/AnalyticsService route group.
func New(deps Deps) http.Handler {
	r := bffserver.NewRouter(bffserver.Options{
		Verifier:          deps.Verifier,
		TrustedProxyCIDRs: deps.TrustedProxyCIDRs,
		Stater:            deps.QueueClient,
		MetricsHandler:    deps.MetricsHandler,
		MetricsMiddleware: deps.MetricsMiddleware,
		FeatureFlagCache:  deps.FeatureFlagCache,
	})

	// Resolve the handlers. Prefer a directly injected handler (tests); fall
	// back to building from the typed gRPC client.
	postH := deps.PostH
	if postH == nil && deps.QueueTypedClient != nil {
		postH = handlers.NewPostHandler(deps.QueueTypedClient.Post)
	}
	accountH := deps.AccountH
	if accountH == nil && deps.QueueTypedClient != nil {
		accountH = handlers.NewAccountHandler(deps.QueueTypedClient.Account)
	}
	accountGroupH := deps.AccountGroupH
	if accountGroupH == nil && deps.QueueTypedClient != nil {
		accountGroupH = handlers.NewAccountGroupHandler(deps.QueueTypedClient.Account)
	}
	accountTagH := deps.AccountTagH
	if accountTagH == nil && deps.QueueTypedClient != nil {
		accountTagH = handlers.NewAccountTagHandler(deps.QueueTypedClient.AccountTag)
	}
	triggerH := deps.TriggerH
	if triggerH == nil && deps.QueueTypedClient != nil {
		triggerH = handlers.NewTriggerHandler(deps.QueueTypedClient.Trigger)
	}
	analyticsH := deps.AnalyticsH
	if analyticsH == nil && deps.QueueTypedClient != nil {
		analyticsH = handlers.NewAnalyticsHandler(deps.QueueTypedClient.Analytics)
	}

	// Authenticated, rate-limited routes.
	bffserver.Authenticated(r, bffserver.Options{
		Verifier:         deps.Verifier,
		FeatureFlagCache: deps.FeatureFlagCache,
		Vertical:         "queue",
		RequestTimeout:   authenticatedGroupTimeout,
	}, func(r chi.Router) {
		if postH != nil {
			r.Route("/api/v1/queue/posts", func(r chi.Router) {
				r.Get("/", postH.List)
				r.Post("/", postH.Create)
				r.Get("/{id}", postH.Get)
				r.Put("/{id}", postH.Update)
				r.Delete("/{id}", postH.Delete)
			})
			// Colon-actions: chi treats ':' as a literal character, so
			// these must be registered as standalone full paths rather
			// than nested inside the r.Route block above — nesting a
			// colon suffix directly after a {param} segment inside a
			// mounted sub-router has proven unreliable elsewhere in this
			// codebase (see services/range-bff/internal/server/server.go's
			// team-member-colon-action comment); a top-level r.Post with
			// the full literal path is the reliable pattern.
			r.With(idemMiddleware(deps.IdemStore)).Post("/api/v1/queue/posts/{id}:schedule", postH.Schedule)
			r.With(idemMiddleware(deps.IdemStore)).Post("/api/v1/queue/posts/{id}:publish", postH.Publish)
			r.Post("/api/v1/queue/posts/{id}:revert", postH.RevertToDraft)
			r.Post("/api/v1/queue/posts:bulk-update", postH.BulkUpdate)
			r.Post("/api/v1/queue/posts:bulk-delete", postH.BulkDelete)
			r.With(idemMiddleware(deps.IdemStore)).Post("/api/v1/queue/posts:bulk-import", postH.BulkImport)
		}

		if accountH != nil {
			r.Route("/api/v1/queue/accounts", func(r chi.Router) {
				r.Get("/", accountH.List)
				r.Post("/", accountH.Create)
				r.Get("/{id}", accountH.Get)
				r.Put("/{id}", accountH.Update)
			})
			r.Post("/api/v1/queue/accounts/{id}:refresh", accountH.Refresh)
			r.Post("/api/v1/queue/accounts/{id}:disconnect", accountH.Disconnect)
			r.Post("/api/v1/queue/accounts:sync", accountH.Sync)
		}

		if accountGroupH != nil {
			r.Route("/api/v1/queue/account-groups", func(r chi.Router) {
				r.Get("/", accountGroupH.List)
				r.Post("/", accountGroupH.Create)
				r.Put("/{id}", accountGroupH.Update)
				r.Delete("/{id}", accountGroupH.Delete)
			})
		}

		if accountTagH != nil {
			r.Route("/api/v1/queue/tags", func(r chi.Router) {
				r.Get("/", accountTagH.List)
				r.Post("/", accountTagH.Create)
				r.Get("/{id}", accountTagH.Get)
				r.Put("/{id}", accountTagH.Update)
				r.Delete("/{id}", accountTagH.Delete)
			})
			r.Post("/api/v1/queue/tags/{id}:assign", accountTagH.Assign)
			r.Post("/api/v1/queue/tags/{id}:unassign", accountTagH.Unassign)
			r.Post("/api/v1/queue/tags/{id}:bulk-assign", accountTagH.BulkAssign)
		}

		if triggerH != nil {
			r.Get("/api/v1/queue/triggers/available-actions", triggerH.ListAvailableActions)
			r.Route("/api/v1/queue/triggers", func(r chi.Router) {
				r.Get("/", triggerH.List)
				r.Post("/", triggerH.Create)
				r.Get("/{id}", triggerH.Get)
				r.Put("/{id}", triggerH.Update)
				r.Delete("/{id}", triggerH.Delete)
			})
		}

		if analyticsH != nil {
			r.Get("/api/v1/queue/analytics/overview", analyticsH.GetOverview)
			r.Get("/api/v1/queue/analytics/platforms", analyticsH.GetPlatformPerformance)
			r.Get("/api/v1/queue/analytics/engagement", analyticsH.GetEngagementTrends)
			r.Get("/api/v1/queue/analytics/top-posts", analyticsH.GetTopPosts)
			r.Get("/api/v1/queue/analytics/frequency", analyticsH.GetPostingFrequency)
		}

		if deps.RangeExercisesH != nil {
			r.Get("/api/v1/queue/range/exercises", deps.RangeExercisesH.List)
		}
	})

	return r
}


