package server

// server_security_gates_test.go — proves queue-bff's two security
// middlewares (auth.RejectAdminRoles, featureflags.RequireVerticalEnabled)
// are actually MOUNTED by New(), not merely importable.
//
// See services/rooms-bff/internal/server/server_security_gates_test.go for
// the audit that motivated this shape: this package's server_test.go
// already has TestQueueVerticalGate_NilCache_PassesThrough (asserts only
// "not 403" — a MISSING gate satisfies that equally well) and
// TestQueueVerticalGate_DepField_IsWired (`_ = New(deps)`, no assertion).
// Both stay green when either r.Use(...) line mounting these gates is
// deleted from server.go. These tests drive real requests through New(deps)
// with a real *auth.JWTVerifier backed by the shared
// platform/libs/go/authtest in-process OIDC harness — the only shape that
// can see the r.Use lines. Ported from rooms-bff via the extracted harness.

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/authtest"
)

const queueGateAudience = "queue-bff"

// queueGateRequest drives one authenticated request through the REAL
// router built by New(), returning the recorder.
func queueGateRequest(t *testing.T, deps Deps, token string) *httptest.ResponseRecorder {
	t.Helper()
	h := New(deps)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rr := httptest.NewRecorder()
	h.ServeHTTP(rr, req)
	return rr
}

// TestRouter_MountsQueueRejectAdminRoles proves New() mounts
// auth.RejectAdminRoles(): an org-admin/admin realm token authenticates
// successfully and is then refused 403 by the route surface. Deleting that
// r.Use line makes this 200.
func TestRouter_MountsQueueRejectAdminRoles(t *testing.T) {
	stub := authtest.NewOIDCStub(t)
	deps := fullyWiredDeps()
	deps.Verifier = authtest.NewVerifier(t, stub, queueGateAudience)
	deps.FeatureFlagCache = makeQueueFlagCache(true) // flag ON, so it cannot be the cause

	for _, role := range []string{"admin", "org-admin"} {
		t.Run(role, func(t *testing.T) {
			token := stub.MintToken(t, authtest.TokenOptions{
				Subject: "admin-1", Audience: queueGateAudience, OrgID: "org-7", Roles: []string{role},
			})
			rr := queueGateRequest(t, deps, token)
			if rr.Code != http.StatusForbidden {
				t.Fatalf("status = %d; want 403 — New() must mount auth.RejectAdminRoles() so a %q realm token cannot reach the route surface", rr.Code, role)
			}
		})
	}
}

// TestRouter_AllowsQueueWorkspaceUser is the positive control for both
// gates: the same request shape with a non-admin token and the flag enabled
// must NOT 403. Without this, a blanket 403 would make the gate test above
// pass for the wrong reason.
func TestRouter_AllowsQueueWorkspaceUser(t *testing.T) {
	stub := authtest.NewOIDCStub(t)
	deps := fullyWiredDeps()
	deps.Verifier = authtest.NewVerifier(t, stub, queueGateAudience)
	deps.FeatureFlagCache = makeQueueFlagCache(true)

	token := stub.MintToken(t, authtest.TokenOptions{
		Subject: "user-42", Audience: queueGateAudience, OrgID: "org-7", Roles: []string{"member"},
	})
	rr := queueGateRequest(t, deps, token)

	if rr.Code == http.StatusForbidden {
		t.Fatalf("status = 403 for a non-admin token with the queue flag ENABLED; body = %s", rr.Body.String())
	}
	if rr.Code == http.StatusUnauthorized {
		t.Fatalf("status = 401 — the minted token should have verified; body = %s", rr.Body.String())
	}
}

// TestRouter_MountsQueueRequireVerticalEnabled proves New() mounts
// featureflags.RequireVerticalEnabled(..., "queue"): a fully valid workspace
// token is refused 403 vertical_disabled when the flag is off. Deleting
// that r.Use line makes this pass through (non-403).
func TestRouter_MountsQueueRequireVerticalEnabled(t *testing.T) {
	stub := authtest.NewOIDCStub(t)
	deps := fullyWiredDeps()
	deps.Verifier = authtest.NewVerifier(t, stub, queueGateAudience)
	deps.FeatureFlagCache = makeQueueFlagCache(false) // queue DISABLED

	token := stub.MintToken(t, authtest.TokenOptions{
		Subject: "user-42", Audience: queueGateAudience, OrgID: "org-7", Roles: []string{"member"},
	})
	rr := queueGateRequest(t, deps, token)

	if rr.Code != http.StatusForbidden {
		t.Fatalf("status = %d; want 403 — New() must mount featureflags.RequireVerticalEnabled(cache, %q); body = %s", rr.Code, "queue", rr.Body.String())
	}
	// Pin the code too: a 403 from RejectAdminRoles would also be a 403
	// here, and only the error code distinguishes which gate fired.
	var body queueFlagDisabledBody
	if err := json.NewDecoder(rr.Body).Decode(&body); err != nil {
		t.Fatalf("decode body: %v", err)
	}
	if body.Error.Code != "vertical_disabled" {
		t.Errorf("error code = %q; want %q — the 403 must come from the feature-flag gate", body.Error.Code, "vertical_disabled")
	}
}


