// ---------- Admin-plane confinement (Security Invariant #8) ----------

// TestRejectAdminRoles_AdminClaims_Returns403 drives auth.RejectAdminRoles()
// directly with an admin-realm-role claim already on the context — this is
// the unit-testable seam given the server tests don't wire a real JWT
// verifier. It proves the exact middleware queue-bff mounts denies admin
// tokens.
func TestRejectAdminRoles_AdminClaims_Returns403(t *testing.T) {
	mw := auth.RejectAdminRoles()

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	claims := auth.Claims{OrgID: "org-7", Subject: "admin-1", Roles: []string{"admin"}}
	req = req.WithContext(auth.ClaimsIntoContext(req.Context(), claims))
	rr := httptest.NewRecorder()

	mw(next).ServeHTTP(rr, req)

	if rr.Code != http.StatusForbidden {
		t.Fatalf("status = %d; want 403 for an admin-realm-role token", rr.Code)
	}
	if nextCalled {
		t.Fatal("next handler must NOT be called for an admin-realm-role token")
	}
}

// TestRejectAdminRoles_NonAdminClaims_PassesThrough asserts a workspace user
// (no admin/org-admin realm role) is let through.
func TestRejectAdminRoles_NonAdminClaims_PassesThrough(t *testing.T) {
	mw := auth.RejectAdminRoles()

	var nextCalled bool
	next := http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		nextCalled = true
		w.WriteHeader(http.StatusOK)
	})

	req := httptest.NewRequest(http.MethodGet, "/api/v1/queue/posts", nil)
	claims := auth.Claims{OrgID: "org-7", Subject: "user-42", Roles: []string{"member"}}
	req = req.WithContext(auth.ClaimsIntoContext(req.Context(), claims))
