	mw(next).ServeHTTP(rr, req)

	if rr.Code == http.StatusForbidden {
		t.Fatal("got 403 for a non-admin claim — RejectAdminRoles must pass it through")
	}
	if !nextCalled {
		t.Fatal("next handler must be called for a non-admin-role token")
	}
}

